    hitInfo.normal = -read_tNormal(coords).rgb;
    hitInfo.color = read_tColor(coords).rgb;
    hitInfo.emissive = read_tColor(coords).rgb * read_tNormal(coords).a * 2.0;

    if (isBackground(getDepth(coords))) {
        hitInfo.emissive = vec3<f32>(0.0);
    }
